    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;
    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->ttl <= 1) {
        // Fix: Set IP destination to original sender, source to router gateway
        __be32 orig_src = ip->saddr;
        ip->daddr = orig_src;  // dst = original src
        ip->saddr = 0xC0A80101; // src = router IP 192.168.1.1

        // Swap MAC addresses to redirect the frame back to the sender
        __u8 tmp_mac[ETH_ALEN];
        #pragma unroll
        for (int i = 0; i < ETH_ALEN; i++) {
            tmp_mac[i] = eth->h_dest[i];
            eth->h_dest[i] = eth->h_source[i];
            eth->h_source[i] = tmp_mac[i];
