        // Update IP fields for the ICMP response
        ip->protocol = IPPROTO_ICMP;
        ip->ttl = 64;

        // Construct the ICMP Time Exceeded header
        struct icmphdr *icmp = (void *)(ip + 1);
        if ((void *)(icmp + 1) > data_end)
            return XDP_DROP;

        icmp->type = 11; // Time Exceeded
        icmp->code = 0;
        icmp->checksum = 0;

        return XDP_TX;
    }

    return XDP_PASS;
